297	func artifactFromPersist(a persistArtifact) Artifact {
298		return Artifact{
299			Name: a.Name, Version: a.Version,
300			Modulus: int(a.Modulus), Constraints: a.Constraints, Hash: a.Hash,
301		}
302	}
303	
304	func definitionMissingf(format string, args ...any) error {
305		return StoreError{Kind: ErrDefinitionMissing.Kind, Detail: fmt.Sprintf(format, args...)}
306	}
307	
308	func artifactMissingf(format string, args ...any) error {
309		return StoreError{Kind: ErrArtifactMissing.Kind, Detail: fmt.Sprintf(format, args...)}
310	}
311	
312	func artifactMismatchf(format string, args ...any) error {
313		return StoreError{Kind: ErrArtifactMismatch.Kind, Detail: fmt.Sprintf(format, args...)}
314	}
