	if r := call("input-check", "--dir", dir, "--name", "mul", "--version", "1",
		"--hash", hash, "--file", goodPath); r.code != 0 ||
		!strings.Contains(r.out, "satisfied=true") || strings.Contains(r.out, "private") {
		t.Fatalf("satisfied check: %+v", r)
	}
