	if r := call("input-check", "--dir", dir, "--name", "mul", "--version", "1",
		"--hash", strings.Repeat("0", 64), "--file", goodPath); r.code != 1 ||
		!strings.Contains(r.err, "artifact mismatch") {
		t.Fatalf("wrong hash: %+v", r)
	}
