package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// These tests cover the CLI contract for a damaged committed definition:
// every data command fails at open with exit code 3 (the existing read-
// failure code), prints no success record / artifact / input-check verdict,
// and leaves data.json byte-for-byte in place.
const cliCorruptDef = `{"modulus":"7","constraints":[
	{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]}]}`

// seedCorruptibleStore drives the CLI through a legal create + import, then
// applies mutate to the parsed data.json and returns the damaged bytes.
func seedCorruptibleStore(t *testing.T, dir string, freezeAndCompile bool, mutate func(map[string]any)) []byte {
	t.Helper()
	work := filepath.Dir(dir)
	defPath := writeFile(t, work, "def.json", cliCorruptDef)
	if r := runCapture(t, "circuit-create", "--dir", dir, "--name", "mul", "--version", "1",
		"--constraints", "1", "--public-inputs", "1", "--private-inputs", "1"); r0(r) {
		t.Fatalf("create: code=%d err=%s", r.code, r.err)
	}
	if r := runCapture(t, "constraint-import", "--dir", dir, "--name", "mul", "--version", "1",
		"--file", defPath); r0(r) {
		t.Fatalf("import: code=%d err=%s", r.code, r.err)
	}
	if freezeAndCompile {
		if r := runCapture(t, "circuit-freeze", "--dir", dir, "--name", "mul", "--version", "1"); r0(r) {
			t.Fatalf("freeze: code=%d err=%s", r.code, r.err)
		}
		if r := runCapture(t, "circuit-compile", "--dir", dir, "--name", "mul", "--version", "1"); r0(r) {
			t.Fatalf("compile: code=%d err=%s", r.code, r.err)
		}
	}

	path := filepath.Join(dir, "data.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var env map[string]any
	if err := json.Unmarshal(raw, &env); err != nil {
		t.Fatal(err)
	}
	mutate(env)
	bad, err := json.MarshalIndent(env, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	bad = append(bad, '\n')
	if err := os.WriteFile(path, bad, 0o644); err != nil {
		t.Fatal(err)
	}
	return bad
}

// r0 reports whether a result failed (non-zero exit).
func r0(r struct {
	code int
	out  string
	err  string
}) bool { return r.code != 0 }

// TestCLICorruptDefinitionExitCode drives each shape of damage through the
// CLI: regardless of draft or frozen/compiled state, reads, compilation and
// input checks must exit 3 without touching the file.
func TestCLICorruptDefinitionExitCode(t *testing.T) {
	removeSide := func(side string) func(map[string]any) {
		return func(env map[string]any) {
			con := definitionConstraint(env)
			delete(con, side)
		}
	}
	setNull := func(path ...string) func(map[string]any) {
		return func(env map[string]any) {
			cur := env
			for i, key := range path {
				if i == len(path)-1 {
					cur[key] = nil
					return
				}
				cur = cur[key].(map[string]any)
			}
		}
	}
	nullTerm := func(env map[string]any) {
		con := definitionConstraint(env)
		con["a"].([]any)[0] = nil
	}

	damage := []struct {
		name   string
		mutate func(map[string]any)
	}{
		{"missing side b", removeSide("b")},
		{"null side a", setNull("circuits")}, // replaced below
		{"null term object", nullTerm},
		{"missing modulus", func(env map[string]any) {
			delete(firstCircuitDefinition(env), "modulus")
		}},
		{"null wire", func(env map[string]any) {
			con := definitionConstraint(env)
			con["a"].([]any)[0].(map[string]any)["wire"] = nil
		}},
	}
	// Build the "null side a" mutation explicitly (arrays are not objects).
	damage[1].mutate = func(env map[string]any) {
		definitionConstraint(env)["a"] = nil
	}

	for _, frozen := range []bool{false, true} {
		state := "draft"
		if frozen {
			state = "frozen-compiled"
		}
		t.Run(state, func(t *testing.T) {
			for _, tc := range damage {
				t.Run(tc.name, func(t *testing.T) {
					dir := filepath.Join(t.TempDir(), "bench")
					bad := seedCorruptibleStore(t, dir, frozen, tc.mutate)

					goodInput := writeFile(t, filepath.Dir(dir), "in.json", cliGoodInput)
					commands := [][]string{
						{"circuit-list", "--dir", dir},
						{"circuit-get", "--dir", dir, "--name", "mul", "--version", "1"},
						{"circuit-compile", "--dir", dir, "--name", "mul", "--version", "1"},
						{"input-check", "--dir", dir, "--name", "mul", "--version", "1",
							"--hash", strings.Repeat("0", 64), "--file", goodInput},
					}
					if !frozen {
						// A mutating command must likewise refuse before writing.
						commands = append(commands, []string{"circuit-freeze", "--dir", dir, "--name", "mul", "--version", "1"})
					} else {
						commands = append(commands, []string{"job-list", "--dir", dir})
					}

					for _, args := range commands {
						code, out, errOut := runCapture(t, args...)
						if code != 3 {
							t.Fatalf("%s: want exit 3, got %d (out=%q err=%q)", args[0], code, out, errOut)
						}
						if out != "" {
							t.Fatalf("%s printed a success record despite corruption: %q", args[0], out)
						}
						if !strings.Contains(errOut, "read failed") || !strings.Contains(errOut, "data corrupt") {
							t.Fatalf("%s: unexpected error text %q", args[0], errOut)
						}
					}

					left, err := os.ReadFile(filepath.Join(dir, "data.json"))
					if err != nil {
						t.Fatal(err)
					}
					if string(left) != string(bad) {
						t.Fatalf("data.json changed after refused commands")
					}
				})
			}
		})
	}
}

// TestCLIDefinitionNullStillCountsOnly keeps the legacy path working at the
// CLI: a record whose definition is null opens and reports a missing
// definition on compile (exit 1), never a read failure.
func TestCLIDefinitionNullStillCountsOnly(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "bench")
	seedCorruptibleStore(t, dir, false, func(env map[string]any) {
		firstCircuitDefinition(env)["constraints"] = nil // make it parse once first
	})
	// Re-seed cleanly: simpler to just set definition=null on a good store.
	dir2 := filepath.Join(t.TempDir(), "bench")
	seedCorruptibleStore(t, dir2, false, func(env map[string]any) {
		firstCircuit(env)["definition"] = nil
	})
	_ = dir

	if r := runCapture(t, "circuit-list", "--dir", dir2); r.code != 0 {
		t.Fatalf("null definition must load: code=%d err=%s", r.code, r.err)
	}
	if r := runCapture(t, "circuit-freeze", "--dir", dir2, "--name", "mul", "--version", "1"); r.code != 0 {
		t.Fatalf("freeze: %s", r.err)
	}
	if r := runCapture(t, "circuit-compile", "--dir", dir2, "--name", "mul", "--version", "1"); r.code != 1 ||
		!strings.Contains(r.err, "constraint definition missing") {
		t.Fatalf("null definition compile: code=%d err=%s", r.code, r.err)
	}
}

func firstCircuit(env map[string]any) map[string]any {
	return env["circuits"].([]any)[0].(map[string]any)
}

func firstCircuitDefinition(env map[string]any) map[string]any {
	return firstCircuit(env)["definition"].(map[string]any)
}

func definitionConstraint(env map[string]any) map[string]any {
	return firstCircuitDefinition(env)["constraints"].([]any)[0].(map[string]any)
}

